      participants: [{ method: "GET", path: "/v1/participants" }, { method: "POST", path: "/v1/participants" }, { method: "GET", path: "/v1/participants/:participantId" }, { method: "POST", path: "/v1/participants/:participantId/attest" }, { method: "POST", path: "/v1/participants/:participantId/revoke" }],
